import itertools
import collections


def task_func(elements, subset_size):
    if subset_size == 2 and len(set(elements)) != len(elements):
        pairs = set(tuple(sorted(combination)) for combination in itertools.combinations(elements, 2))
        return collections.Counter(sum(pair) for pair in pairs)
    combinations = list(itertools.combinations(elements, subset_size))
    sums = [sum(combination) for combination in combinations]
    return collections.Counter(sums)

