import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:

    def reverse_matched_words(text):
        if pattern:
            parts = re.split(r"(\s+)", text)
            word_idx = [i for i in range(0, len(parts), 2) if parts[i]]
            matched_idx = [i for i in word_idx if re.search(pattern, parts[i])]
            matched_vals = [parts[i] for i in matched_idx][::-1]
            for i, val in zip(matched_idx, matched_vals):
                parts[i] = val
            return "".join(parts)
        words = text.split()
        matched_words = [word for word in words if re.search(pattern, word)][::-1]
        new_words = [
            matched_words.pop(0) if re.search(pattern, word) else word for word in words
        ]
        return " ".join(new_words)

    new_df = df.copy()
    if not pattern:
        return new_df
    new_df[column_name] = new_df[column_name].apply(reverse_matched_words)
    return new_df

