from scipy.spatial.distance import pdist, squareform


def task_func(array):
    if not isinstance(array, list):
        raise TypeError("Input must be a list.")

    if not all(isinstance(sublist, list) for sublist in array):
        raise TypeError("Input must be a list of lists.")

    for sublist in array:
        if not all(isinstance(item, (int, float)) for item in sublist):
            raise TypeError("All elements in the sublists must be int or float.")

    columns = [chr(65 + i) for i in range(len(array[0]))]
    df = pd.DataFrame(array, columns=columns)

    mixed_object = False
    if all(len(sublist) == len(columns) for sublist in array):
        for j, col in enumerate(columns):
            values = [sublist[j] for sublist in array]
            floats = [v for v in values if isinstance(v, float)]
            ints = [v for v in values if isinstance(v, int) and not isinstance(v, bool)]
            if (
                floats
                and ints
                and len(floats) + len(ints) == len(values)
                and all(math.isfinite(v) for v in floats)
                and all(-(2 ** 63) <= v <= 2 ** 63 - 1 for v in ints)
            ):
                df[col] = pd.Series(values, index=df.index, dtype=object)
                mixed_object = True

    if mixed_object:
        distances = pdist(np.asarray(df.values, dtype=float), metric="euclidean")
    else:
        distances = pdist(df.values, metric="euclidean")
    distance_matrix = pd.DataFrame(
        squareform(distances), index=df.index, columns=df.index
    )

    return df, distance_matrix

