import pandas as pd
from sklearn.cluster import DBSCAN

def task_func(data, cols):
    df = pd.DataFrame(data, columns=cols)
    dbscan = DBSCAN(eps=3, min_samples=2)
    df['Cluster'] = dbscan.fit_predict(df)
    if df.shape[1] == 2:
        labels = df['Cluster'].tolist()
        values = df.iloc[:, 0].tolist()
        unique = sorted(set(l for l in labels if l != -1))
        if len(unique) > 1:
            mins = {}
            for l, v in zip(labels, values):
                if l != -1:
                    mins[l] = v if l not in mins else min(mins[l], v)
            order = sorted(unique, key=lambda l: (mins[l], l))
            mapping = {old: i for i, old in enumerate(order)}
            df['Cluster'] = [mapping[l] if l != -1 else -1 for l in labels]
    return df

