import re
import math

def task_func(s):
    numbers = re.findall(r'\b\d+(?:\.\d+)?\b', s)  # Use non-capturing group for decimals
    if re.search(r'\b[A-Za-z]+\s*:\s*(\d+(?:\.\d+)?)\b', s):
        excluded_starts = {match.start(1) for match in re.finditer(r'\b[A-Za-z]+\s*:\s*(\d+(?:\.\d+)?)\b', s)}
        numbers = [match.group() for match in re.finditer(r'\b\d+(?:\.\d+)?\b', s) if match.start() not in excluded_starts]
    count = len(numbers)
    sqrt_sum = sum(math.sqrt(float(num)) for num in numbers if num)  # Ensure conversion to float
    return count, sqrt_sum

import re
import math

def task_func(s):
    numbers = []
    for field in s.split(','):
        m = re.fullmatch(r'\s*[A-Za-z]+\s*:\s*(\d+(?:\.\d+)?)\s*', field)
        if m:
            numbers.append(m.group(1))
        else:
            numbers.extend(re.findall(r'\b\d+(?:\.\d+)?\b', field))
    count = len(numbers)
    sqrt_sum = sum(math.sqrt(float(num)) for num in numbers if num)
    return count, sqrt_sum

