from collections import Counter
import itertools
import operator

def task_func(list_of_menuitems):
    flat_list = list(itertools.chain(*list_of_menuitems))

    counter = Counter(flat_list)

    if counter and list(counter.values()).count(max(counter.values())) > 1:
        return max(item for item, count in counter.items() if count == max(counter.values()))
    return max(counter.items(), key=operator.itemgetter(1))[0]

