                continue
            if word not in STOPWORDS:
                filtered.append(word)
        words = filtered
        sentence_counts[f"Sentence {i+1}"] = len(words)

    sentence_counts = pd.Series(sentence_counts)
    return sentence_counts

import math
import itertools
from functools import reduce

def task_func(numbers):
    sum_log_products = 0

    if len(set(numbers)) != len(numbers):
        seen = set()
        for r in range(1, len(numbers) + 1):
            for combination in itertools.combinations(numbers, r):
                key = tuple(sorted(combination))
                if key in seen:
                    continue
                seen.add(key)
                product = reduce(lambda x, y: x * y, combination)
                sum_log_products += math.log(product)
        return sum_log_products

    for r in range(1, len(numbers) + 1):
        combinations = itertools.combinations(numbers, r)
        for combination in combinations:
            product = reduce(lambda x, y: x * y, combination)
            sum_log_products += math.log(product)

    return sum_log_products

