import pandas as pd
import numpy as np
import unicodedata

DEFAULT_COLUMNS = ['Element', 'Count']


def _is_pict(cp):
    return (0x1F000 <= cp <= 0x1FAFF or 0x1FC00 <= cp <= 0x1FFFD or 0x2600 <= cp <= 0x27BF
            or 0x2300 <= cp <= 0x23FF or 0x2B00 <= cp <= 0x2BFF or 0x2194 <= cp <= 0x21AA
            or cp in (0x00A9, 0x00AE, 0x203C, 0x2049, 0x2122, 0x2139, 0x3030, 0x303D, 0x3297, 0x3299))


def _gb_type(ch):
    cp = ord(ch)
    cat = unicodedata.category(ch)
    if cp == 0x0D:
        return 'CR'
    if cp == 0x0A:
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if (cat in ('Mn', 'Me') or cp == 0x200C or 0xFE00 <= cp <= 0xFE0F or 0xE0100 <= cp <= 0xE01EF
            or 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F or 0xFF9E <= cp <= 0xFF9F):
        return 'Extend'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97F:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    if cat == 'Mc':
        return 'SpacingMark'
    if cat in ('Cc', 'Zl', 'Zp', 'Cf'):
        return 'Control'
    if _is_pict(cp):
        return 'Pict'
    return 'Other'


def _grapheme_count(s):
    count = 0
    prev = None
    ri_run = 0
    pict_ext = False
    zwj_pict = False
    for ch in s:
        t = _gb_type(ch)
        if prev is None:
            brk = True
        elif prev == 'CR' and t == 'LF':
            brk = False
        elif prev in ('CR', 'LF', 'Control') or t in ('CR', 'LF', 'Control'):
            brk = True
        elif prev == 'L' and t in ('L', 'V', 'LV', 'LVT'):
            brk = False
        elif prev in ('LV', 'V') and t in ('V', 'T'):
            brk = False
        elif prev in ('LVT', 'T') and t == 'T':
            brk = False
        elif t in ('Extend', 'ZWJ', 'SpacingMark'):
            brk = False
        elif prev == 'ZWJ' and t == 'Pict' and zwj_pict:
            brk = False
        elif prev == 'RI' and t == 'RI' and ri_run % 2 == 1:
            brk = False
        else:
            brk = True
        if brk:
            count += 1
        if t == 'RI':
            ri_run = ri_run + 1 if prev == 'RI' else 1
        else:
            ri_run = 0
        if t == 'Pict':
            pict_ext = True
            zwj_pict = False
        elif t == 'Extend':
            zwj_pict = False
        elif t == 'ZWJ':
            zwj_pict = pict_ext
            pict_ext = False
        else:
            pict_ext = False
            zwj_pict = False
        prev = t
    return count


def task_func(elements, include_index=False):
    elements_series = pd.Series(elements)
    count_series = elements_series.apply(lambda x: _grapheme_count(x) if isinstance(x, str) and (not x.isascii() or '\r\n' in x) else len(x))
    data_dict = {'Element': elements_series, 'Count': count_series}
    if include_index:
        data_dict['Index'] = np.arange(len(elements))
    count_df = pd.DataFrame(data_dict)
    if include_index:
        count_df = count_df[['Index', 'Element', 'Count']]  # Reordering columns to put 'Index' first
    return count_df

import pandas as pd
from scipy.stats import skew

def task_func(df):
    if not isinstance(df, pd.DataFrame) or df.empty:
        raise ValueError("Input must be a non-empty pandas DataFrame.")

    last_col = df.columns[-1]
    col = df[last_col].dropna()
    if pd.api.types.is_numeric_dtype(col) and not pd.api.types.is_bool_dtype(col) and len(col) >= 3:
        vals = col.astype(float)
        if ((vals != float('inf')) & (vals != float('-inf'))).all():
            n = len(vals)
            d = vals - vals.mean()
            m2 = (d ** 2).mean()
            m3 = (d ** 3).mean()
            if m2 > 0:
                return float((n * (n - 1)) ** 0.5 / (n - 2) * m3 / m2 ** 1.5)
    skewness = skew(df[last_col].dropna())  # dropna() to handle NaN values

    return skewness

