from decimal import Decimal

def task_func(my_obj):
    class DateTimeEncoder(json.JSONEncoder):
        def default(self, obj):
            if isinstance(obj, datetime):
                return obj.isoformat()
            if isinstance(obj, Decimal):
                return str(obj)
            return json.JSONEncoder.default(self, obj)
    def has_non_ascii_value(obj, seen):
        if isinstance(obj, str):
            return any(ord(char) > 127 for char in obj)
        if isinstance(obj, (dict, list, tuple)) and id(obj) not in seen:
            seen.add(id(obj))
            values = obj.values() if isinstance(obj, dict) else obj
            return any(has_non_ascii_value(value, seen) for value in values)
        return False
    if has_non_ascii_value(my_obj, set()):
        return json.dumps(my_obj, cls=DateTimeEncoder, ensure_ascii=False)
    return json.dumps(my_obj, cls=DateTimeEncoder)

