import re
import pandas as pd
import numpy as np
# Constants
DATA_PATTERN = r'>\d+\.\d+<'


def task_func(dataframe, data_pattern=DATA_PATTERN):
    def _extract(x):
        if pd.notnull(x) and len(list(re.finditer(data_pattern, x))) > 1:
            return float(list(re.finditer(data_pattern, x))[-1].group(0)[1:-1])
        return float(re.search(data_pattern, x).group(0)[1:-1]) if pd.notnull(x) and re.search(data_pattern, x) else np.nan
    for col in dataframe.columns:
        dataframe[col] = dataframe[col].apply(_extract)
    return dataframe

