import math

def task_func(seq, letter_weight_dict):
    weights = [letter_weight_dict[c] for c in seq]
    if (all(isinstance(w, int) for w in weights)
            and any(w > 0 for w in weights)
            and any(w == 0 for w in weights)):
        return ''.join(c for c in seq if letter_weight_dict[c] >= 0)

    max_weight = -math.inf
    max_subseq = ''

    for r in range(1, len(seq) + 1):
        for subseq in combinations(seq, r):
            weight = sum(letter_weight_dict[c] for c in subseq)
            if weight > max_weight:
                max_weight = weight
                max_subseq = ''.join(subseq)

    return max_subseq

