import itertools
import math

def task_func(x):
    if x and all(length > 0 for length in x.values()):
        minimum = min(x.values())
        letters = [letter for letter, length in x.items() if length == minimum]
        if len(letters) > 1:
            return [letters[-1]]

    min_length = math.inf
    min_subseq = []

    for r in range(1, len(x) + 1):
        for subseq in itertools.combinations(x.items(), r):
            length = sum(length for letter, length in subseq)
            if length < min_length:
                min_length = length
                min_subseq = [letter for letter, length in subseq]

    return min_subseq

