import numpy as np
from scipy.stats import mode

def task_func(list_of_lists):
    merged_list = np.array([item for sublist in list_of_lists for item in sublist])
    mode_value, mode_count = mode(merged_list)
    if merged_list.ndim == 1 and merged_list.size > 0:
        vals, counts = np.unique(merged_list, return_counts=True)
        tied_vals = vals[counts == counts.max()]
        if tied_vals.size > 1:
            mask = np.isin(merged_list, tied_vals)
            first = merged_list[np.argmax(mask)]
            if np.ndim(mode_value):
                mode_value = np.full_like(mode_value, first)
            else:
                mode_value = first
    return mode_value, mode_count

